import{z as i,x as A,o as t,c as d,q as s,j as n,D as o,d as E,s as B,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const G=JSON.parse('{"title":"运行时与 GC 直觉","description":"","frontmatter":{"title":"运行时与 GC 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/runtime-gc.md","filePath":"cs/runtime-gc.md","lastUpdated":1791063341000}'),c={name:"cs/runtime-gc.md"};function p(m,a,C,h,u,f){const r=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="运行时与-gc-直觉" tabindex="-1">运行时与 GC 直觉 <a class="header-anchor" href="#运行时与-gc-直觉" aria-label="Permalink to &quot;运行时与 GC 直觉&quot;">​</a></h1><div class="epigraph"><p>语言运行时管理栈上的帧之外的堆；垃圾回收从根出发标记仍可达的对象，其余当作可回收。</p><footer>—— 据 McCarthy, Recursive Functions of Symbolic Expressions, 1960；Jones, Hosking and Moss, The Garbage Collection Handbook 整理</footer></div><p>上一课<a href="/cs/load-dynlink">加载与动态链接</a>让映像进了地址空间。本课不重写 GOT。缺口是：程序还要<strong>分配</strong>生命周期超出当前调用的对象。C 把责任交给 <code>malloc</code>/<code>free</code>；带 GC 的语言在运行时里藏一套堆。本课只给标记-清扫的直觉，作为编译课程的收束；操作系统课从内核与用户态再剖进程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/calling-convention-stack">栈</a>随调用生灭，放不下任意寿命的对象。堆：运行时向操作系统要一大块（后课 <code>mmap</code>），再切成对象。手工释放会悬空与泄漏。GC：程序员不写 <code>free</code>，运行时找「从根走指针到不了」的块。根：寄存器、栈上的指针槽、全局。编译器必须让 GC 能认指针——栈图、或保守把像指针的字都当根。</p><p>缺口是这套分工，不是 JVM 规范全文。</p><h3 id="gc-不是「无限内存」" tabindex="-1">GC 不是「无限内存」 <a class="header-anchor" href="#gc-不是「无限内存」" aria-label="Permalink to &quot;GC 不是「无限内存」&quot;">​</a></h3><p>回收有暂停、有碎片、有与写屏障相关的吞吐代价。实时性与尾延迟是边界。本课只钉可达性 = 活；循环引用在追踪式 GC 下可收，引用计数单独处理循环。<span class="marginnote">常见误区：初学者容易以为「有 GC 就不会内存溢出」——GC 只回收「够不着」的块；集合里一直攥着引用（缓存不设上限、监听器没解绑）的对象永远可达，堆照样涨爆，这是托管语言应用最常见的内存故障形态。</span></p><p><span class="marginnote">McCarthy 1960 的 Lisp 已用标记回收。Jones 等手册分标记-清扫、复制、分代。本课不把分代写成实现作业。编译栏到堆与根为止，下一课内核/用户态。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配：空闲链表或 bump 指针（复制式）。标记-清扫：从根 DFS/BFS 标记，再扫堆清未标记。复制式：from/to 半区，活对象搬到 to，更新指针。分代：新对象多早死，先扫幼代。<span class="marginnote">数字实例：幼代回收通常几毫秒量级，老代回收可能要几十到几百毫秒——分代的赌注是「绝大多数对象活不过第一次回收」；若你的负载以长命大对象为主，赌注反着输：对象不停晋升，老代回收反而被频繁触发。</span></p>',11)),(t(),n(l,null,{default:o(()=>[B(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%EF%BC%9A%E6%A0%88%20%2F%20%E5%AF%84%E5%AD%98%E5%99%A8%20%2F%20%E5%85%A8%E5%B1%80%22%5D%20--%3E%20MARK%5B%22%E8%BF%BD%E8%B8%AA%E5%8F%AF%E8%BE%BE%22%5D%0A%20%20MARK%20--%3E%20LIVE%5B%22%E6%B4%BB%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20MARK%20--%3E%20DEAD%5B%22%E4%B8%8D%E5%8F%AF%E8%BE%BE%20%E2%86%92%20%E5%9B%9E%E6%94%B6%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/bfs-unweighted"},"图的遍历"),E("在这里作用于堆图。指针必须可识别，否则保守 GC 可能漏收或误钉。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("编译器为 GC 服务：不把指针藏进非指针表示而不登记；写屏障在分代/增量里通知运行时。无 GC 的语言运行时仍有启动码、异常栈展开、线程局部，本课以堆为中心。ABI 的寄存器在 GC 安全点必须可见——与着色、调用约定一致。"),e("span",{class:"marginnote"},"直觉类比：GC 像图书馆定期盘点——管理员不问「哪本书没人要」，而是从「当前读者手上」的书（根：栈、寄存器、全局）顺着借阅链一路点下去，链上够不着的书当作无主收走；书从不需要自己举手申报「没人要我」。")],-1)),(t(),n(l,null,{default:o(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALLOC%5B%22%E6%96%B0%E5%AF%B9%E8%B1%A1%E5%88%86%E9%85%8D%E8%BF%9B%E5%B9%BC%E4%BB%A3%22%5D%20--%3E%20SURV%7B%22%E4%B8%80%E6%AC%A1%E5%B9%BC%E4%BB%A3%E5%9B%9E%E6%94%B6%E5%90%8E%E8%BF%98%E6%B4%BB%E7%9D%80%EF%BC%9F%22%7D%0A%20%20SURV%20--%20%22%E5%90%A6%22%20--%3E%20DIE%5B%22%E5%B0%B1%E5%9C%B0%E5%9B%9E%E6%94%B6%20%E5%A4%A7%E5%A4%9A%E6%95%B0%E5%AF%B9%E8%B1%A1%E5%88%B0%E6%AD%A4%E4%B8%BA%E6%AD%A2%22%5D%0A%20%20SURV%20--%20%22%E6%98%AF%22%20--%3E%20AGE%5B%22%E5%B9%B4%E9%BE%84%E5%8A%A0%E4%B8%80%20%E7%95%99%E5%9C%A8%E5%B9%BC%E4%BB%A3%22%5D%0A%20%20AGE%20--%3E%20PROM%5B%22%E7%86%AC%E8%BF%87%E9%98%88%E5%80%BC%20%E6%99%8B%E5%8D%87%E8%80%81%E4%BB%A3%22%5D%0A%20%20PROM%20--%3E%20MAJ%5B%22%E8%80%81%E4%BB%A3%E4%BD%8E%E9%A2%91%E5%9B%9E%E6%94%B6%20%E4%BB%A3%E4%BB%B7%E5%A4%A7%E4%BD%86%E7%A8%80%E5%B0%91%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内核分配器、不写页表。不把引用计数算法写完。并发 GC 的漏标问题点名即止。后课操作系统从特权级与进程映像接过「谁给运行时那块虚拟内存」。编译课程到此：从源字符串到带堆的可执行运行时。</p><p>后课默认：用户态运行时管理堆；GC 按可达性回收。内核与用户态是下一课程的第一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>运行时在栈外提供堆；GC 按根的可达性回收。</li><li>标记-清扫与复制是基本图像；分代是启发式。</li><li>编译器须配合根与指针表示。</li><li>出处：McCarthy, 1960；Jones, Hosking and Moss, <em>The Garbage Collection Handbook</em>。</li></ul>',5))])}const g=i(c,[["render",p]]);export{G as __pageData,g as default};
